import { defineConfig } from 'vite';
import { resolve } from 'path';
import { readdirSync, readFileSync, existsSync } from 'fs';

// Discover per-entry changelog HTML files generated by
// scripts/build-changelog.mjs. The script is invoked automatically
// via the predev/prebuild npm hooks (see package.json), so this
// directory will exist by the time Vite reads its config.
//
// `index.html` is filtered out because it's the changelog landing page
// (now lives at src/changelog/index.html as part of the /changelog/
// URL namespace) and is registered separately below.
const CHANGELOG_DIR = resolve(__dirname, 'src/changelog');
const changelogEntries = existsSync(CHANGELOG_DIR)
  ? readdirSync(CHANGELOG_DIR)
      .filter(f => f.endsWith('.html') && f !== 'index.html')
      .reduce((acc, file) => {
        const id = file.replace(/\.html$/, '');
        acc[`changelog-${id}`] = resolve(CHANGELOG_DIR, file);
        return acc;
      }, {})
  : {};

/**
 * htmlPartials — replaces `<!-- @include name -->` markers in any HTML
 * entry with the contents of `src/partials/<name>.html`.
 *
 * Runs at both dev-serve time (transformIndexHtml on each request) and
 * build time (transformIndexHtml on each Rollup input). Per-entry
 * changelog pages get the same treatment because they're listed as
 * Rollup inputs above.
 *
 * In dev, edits to partials trigger a full page reload.
 */
function htmlPartials() {
  const partialsDir = resolve(__dirname, 'src/partials');
  const read = (name) =>
    readFileSync(resolve(partialsDir, `${name}.html`), 'utf8');

  return {
    name: 'html-partials',
    transformIndexHtml: {
      order: 'pre',
      handler(html) {
        return html.replace(
          /<!--\s*@include\s+([a-z0-9_-]+)\s*-->/g,
          (_, name) => read(name)
        );
      },
    },
    configureServer(server) {
      server.watcher.add(partialsDir);
      server.watcher.on('change', (file) => {
        if (file.startsWith(partialsDir)) {
          server.ws.send({ type: 'full-reload' });
        }
      });
    },
  };
}

export default defineConfig({
  root: 'src',
  // OG SVG images live in public/ so they're served at stable /og/<id>.svg
  // URLs without Vite's content-hashing — social platforms need stable URLs.
  publicDir: resolve(__dirname, 'public'),
  plugins: [htmlPartials()],
  build: {
    outDir: '../dist',
    emptyOutDir: true,
    rollupOptions: {
      input: {
        // ─── Root / cross-platform ────────────────────────────────
        main:      resolve(__dirname, 'src/index.html'),
        about:     resolve(__dirname, 'src/about/index.html'),
        changelog: resolve(__dirname, 'src/changelog/index.html'),

        // ─── WordPress platform ───────────────────────────────────
        // /wordpress/* is the future-aware namespace: a second
        // platform (Shopify, Figma, …) gets its own sibling folder
        // and these entries don't need to move.
        wordpress:           resolve(__dirname, 'src/wordpress/index.html'),
        wordpressGetStarted: resolve(__dirname, 'src/wordpress/get-started/index.html'),
        wordpressComponents: resolve(__dirname, 'src/wordpress/components/index.html'),
        wordpressLayouts:    resolve(__dirname, 'src/wordpress/layouts/index.html'),
        wordpressDocs:       resolve(__dirname, 'src/wordpress/docs/index.html'),
        wordpressSkills:     resolve(__dirname, 'src/wordpress/skills/index.html'),

        // Per-changelog-entry pages (auto-generated by
        // scripts/build-changelog.mjs into src/changelog/<id>.html).
        ...changelogEntries,
      }
    },
    // Copy the generated OG SVG files alongside the build.
    assetsInlineLimit: 0,
  },
  server: {
    port: 3000,
    open: true,
    fs: {
      // Allow serving files from the monorepo root so we can @import
      // the sibling packages (tokens, core-css) directly.
      allow: ['../../..']
    }
  }
});
